css:
@page{
    size:A4;
    margin: 1cm;
}

h1,
h2,
h3,
h4,
h5{
    margin:0;
}

.total{
    font-size: large;
    font-weight:bold;
}

.header{
    display:flex;
    flex-direction:column;
    align-items:center;
    gap:10px;
}

.details{
    display:flex;
    flex-direction:column;
    gap:2px;
    margin-top:10px;
    margin-bottom:10px;
}

.text{
    display:flex;
    align-items:center;
    gap:5px;
}

.footer{
    margin-top:10px;
}

.res{
    text-align:center;
}
